   169	/**
   170	 * @param array<int,string> $args
   171	 * @return array<string,mixed>
   172	 */
   173	function taxonomy_admin_decode_cli_json(string $text): ?array
   174	{
   175	  $decoded = json_decode($text, true);
   176	  if (is_array($decoded)) {
   177	    return $decoded;
   178	  }
   179	
   180	  $start = strpos($text, '{');
   181	  $end = strrpos($text, '}');
   182	  if ($start === false || $end === false || $end <= $start) {
   183	    return null;
   184	  }
   185	  $decoded = json_decode(substr($text, $start, $end - $start + 1), true);
   186	  return is_array($decoded) ? $decoded : null;
   187	}
