   197	function taxonomy_admin_run_cli(array $args): array
   198	{
   199	  if (!function_exists('exec')) {
   200	    return ['ok' => false, 'error' => 'PHP exec() đang bị tắt nên admin không thể chạy taxonomy CLI.'];
   201	  }
   202	  $script = taxonomy_admin_root_path('tools/manage_taxonomy.py');
   203	  if (!file_exists($script)) {
   204	    return ['ok' => false, 'error' => 'Không tìm thấy tools/manage_taxonomy.py'];
   205	  }
   206	  $candidates = [];
   207	  $envPython = trim((string) getenv('KDTD_PYTHON_BIN'));
   208	  if ($envPython !== '') {
   209	    $candidates[] = $envPython;
   210	  }
   211	  $candidates[] = 'python3';
   212	  $candidates[] = 'python';
   213	  $candidates = array_values(array_unique($candidates));
   214	
   215	  $last = null;
   216	  foreach ($candidates as $python) {
   217	    $pythonCmd = function_exists('public_rebuild_python_command')
   218	      ? public_rebuild_python_command((string) $python)
   219	      : escapeshellcmd((string) $python);
   220	    $command = taxonomy_admin_python_env_prefix() . $pythonCmd . ' ' . escapeshellarg($script);
   221	    foreach ($args as $arg) {
   222	      $command .= ' ' . escapeshellarg($arg);
   223	    }
   224	    $command .= ' 2>&1';
   225	    $output = [];
   226	    $exitCode = 1;
   227	    exec($command, $output, $exitCode);
   228	    $text = implode("\n", $output);
   229	    $decoded = taxonomy_admin_decode_cli_json($text);
   230	    $last = is_array($decoded) ? $decoded : [
   231	      'ok' => false,
   232	      'error' => trim($text) !== '' ? trim($text) : ('Không parse được JSON từ taxonomy CLI: ' . json_last_error_msg()),
   233	    ];
   234	    $last['exit_code'] = $exitCode;
   235	    $last['python'] = (string) $python;
   236	    if (!empty($last['ok'])) {
   237	      return $last;
   238	    }
   239	  }
   240	  return is_array($last) ? $last : ['ok' => false, 'error' => 'Không chạy được taxonomy CLI.'];
   241	}
